import { builder } from './builder';
import './types/user';
import './types/post';
import './queries';

export const schema = builder.toSchema();

import SchemaBuilder from '@pothos/core';
import PrismaPlugin from '@pothos/plugin-prisma-next';
import RelayPlugin from '@pothos/plugin-relay';
import type { Contract } from './contract';
import { db } from './database';

export const builder = new SchemaBuilder<{ PrismaContract: Contract }>({
  plugins: [RelayPlugin, PrismaPlugin],
  prisma: { client: db },
});

import { DatabaseSync } from 'node:sqlite';
import sqlite from '@prisma/orm-sqlite/runtime';
import { contractFromJson } from '@prisma/orm-sqlite/static';
import type { Contract } from './contract';
import contractJson from './contract.json';

// The playground backs `node:sqlite` with SQLite compiled to WebAssembly.
const path = 'publishing.db';
const seed = new DatabaseSync(path);
seed.exec(`
DROP TABLE IF EXISTS posts;
DROP TABLE IF EXISTS users;
CREATE TABLE users (id INTEGER PRIMARY KEY, firstName TEXT NOT NULL, lastName TEXT NOT NULL, email TEXT NOT NULL UNIQUE);
CREATE TABLE posts (id INTEGER PRIMARY KEY, title TEXT NOT NULL, published INTEGER NOT NULL, authorId INTEGER NOT NULL REFERENCES users(id));
INSERT INTO users VALUES (1, 'Maya', 'Chen', 'maya@example.com'), (2, 'Leo', 'Silva', 'leo@example.com');
INSERT INTO posts VALUES
(1, 'Starting a seed library', 1, 1),
(2, 'A guide to composting', 1, 1),
(3, 'Planning the spring exchange', 0, 1),
(4, 'Watering through summer', 1, 2);
`);
seed.close();

export const contract = contractFromJson<Contract>(contractJson);
export const db = sqlite({ contract, path });

import { builder } from './builder';

builder.queryType({
  fields: (t) => ({
    recentPosts: t.prismaField({
      type: ['Post'],
      query: { where: { published: 1 }, orderBy: { id: 'desc' }, limit: 10 },
    }),
  }),
});

builder.queryFields((t) => ({
  author: t.prismaField({
    type: 'User',
    nullable: true,
    args: { id: t.arg.int({ required: true }) },
    query: (args) => ({ where: { id: args.id } }),
  }),
  posts: t.prismaConnection({
    type: 'Post',
    totalCount: true,
    args: { newestFirst: t.arg.boolean() },
    // Chooses the direction per request; the plugin reverses it for backward pages.
    query: (args) => ({
      where: { published: 1 },
      orderBy: { id: args.newestFirst ? 'desc' : 'asc' },
    }),
  }),
}));

import { builder } from '../builder';

builder.prismaObject('Post', {
  fields: (t) => ({
    id: t.exposeID('id'),
    title: t.exposeString('title'),
    author: t.relation('author'),
  }),
});

import { builder } from '../builder';

builder.prismaObject('User', {
  fields: (t) => ({
    id: t.exposeID('id'),
    email: t.exposeString('email'),
    // Selects its columns only when a query asks for this field.
    fullName: t.string({
      select: ['firstName', 'lastName'],
      resolve: (user) => `${user.firstName} ${user.lastName}`,
    }),
  }),
});

// Pages through the relation inside the query that loads the user.
builder.prismaObjectField('User', 'postConnection', (t) =>
  t.relatedConnection('posts', {
    query: { where: { published: 1 } },
    totalCount: true,
  }),
);

